            }
            const interned = internName(c, name_buf.items);
            _ = try c.cross_chunk_names.put(allocator, entry.sym_ref, interned);
        }
        for (cp_mut_slice(&chunks)) |*chunk| {
            _ = &chunk;
            if ((((chunk.*).content != .javascript) or ((chunk.*).renamer != .MinifyRenamer))) {
                continue;
            }
            const js = (&(chunk.*).content.javascript);
            const r = (chunk.*).renamer.MinifyRenamer;
            for (cp_iter_slice(js.exports_to_other_chunks.keys())) |sym_ref| {
                _ = &sym_ref;
                if (c.cross_chunk_names.get(sym_ref)) |name| {
                    _ = &name;
                    _ = try r.pin(sym_ref, name);
                }
            }
            for (js.imports_from_other_chunks.values()) |items| {
                _ = &items;
                for (cp_iter_slice(items.slice())) |item| {
                    _ = &item;
                    if (c.cross_chunk_names.get(item.@"ref")) |name| {
                        _ = &name;
                        _ = try r.pin(item.@"ref", name);
                    }
                }
            }
        }
}

pub fn applyToClauses(c: *LinkerContext, chunks: []Chunk) void {
        if ((c.cross_chunk_names.count() == 0)) {
            return;
        }
        for (cp_mut_slice(&chunks)) |*chunk| {
            _ = &chunk;
            if (((chunk.*).content != .javascript)) {
                continue;
            }
            var js = (&(chunk.*).content.javascript);
            _ = &js;
            var export_iter = js.exports_to_other_chunks.iterator();
            _ = &export_iter;
            while (export_iter.next()) |entry| {
                if (c.cross_chunk_names.get(entry.key_ptr.*)) |name| {
                    _ = &name;
                    entry.value_ptr.* = name;
                }
            }
            for (cp_iter_slice(js.cross_chunk_suffix_stmts.slice())) |stmt| {
                _ = &stmt;
                if ((stmt.data == .s_export_clause)) {
                    for (stmt.data.s_export_clause.items) |*item| {
                        _ = &item;
                        if ((if (@typeInfo(@TypeOf((item.*))) == .@"enum" or @typeInfo(@TypeOf((item.*))) == .@"union") @tagName((item.*)) else (item.*).name).@"ref") |r_ref| {
                            _ = &r_ref;
                            if (c.cross_chunk_names.get(r_ref)) |name| {
                                _ = &name;
                                (item.*).alias = name;
                            }
                        }
                    }
                }
            }
            for (cp_iter_slice(js.cross_chunk_prefix_stmts.slice())) |stmt| {
                _ = &stmt;
                if ((stmt.data == .s_import)) {
                    for (stmt.data.s_import.items) |*item| {
                        _ = &item;
                        if ((if (@typeInfo(@TypeOf((item.*))) == .@"enum" or @typeInfo(@TypeOf((item.*))) == .@"union") @tagName((item.*)) else (item.*).name).@"ref") |r_ref| {
                            _ = &r_ref;
                            if (c.cross_chunk_names.get(r_ref)) |name| {
                                _ = &name;
                                (item.*).alias = name;
                            }
                        }
                    }
                }
            }
        }
}
